<template><a-card><a-space direction="vertical" fill><a-space><a-input v-model="q" placeholder="搜索资源" allow-clear @press-enter="loadSearch"/><a-button type="primary" @click="load">刷新</a-button></a-space><a-table :data="rows" :loading="loading" row-key="id" :pagination="{pageSize:50}"><template #columns><a-table-column title="ID" data-index="id"/><a-table-column title="名称" data-index="name"/><a-table-column title="大小" data-index="size"/><a-table-column title="状态" data-index="status"/><a-table-column title="创建时间" data-index="created_at"/></template></a-table></a-space></a-card></template><script setup lang="ts">import {onMounted,ref} from "vue";import {catalog} from "../api";import {Message} from "@arco-design/web-vue";const rows=ref<any[]>([]),loading=ref(false),q=ref("");async function load(){loading.value=true;try{const r=await catalog.list({page:1,size:50});rows.value=r.data?.data?.items||r.data?.items||[]}catch(e:any){Message.error(e.response?.data?.detail||"加载失败")}finally{loading.value=false}}async function loadSearch(){if(!q.value)return load();const r=await catalog.search({q:q.value,limit:100});rows.value=r.data?.data||r.data||[]}onMounted(load)</script>